<?php $page_title='Reports'; require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE reports SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Report updated.');redirect('reports.php');}
