?><section class="admin-page-head"><div><span class="kicker">ADMIN / SAFETY</span><h1>Reports & Complaints</h1><p>Review community, food and user reports.</p></div></section><div class="admin-table-card"><div class="table-wrap"><table><thead><tr><th>Reporter</th><th>Target</th><th>Reason</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['reporter']?:'Anonymous')?></td><td><?=e($r['target_type'])?> #<?=intval($r['target_id'])?></td><td><?=e($r['reason'])?></td><td><?=e($r['details']?:'—')?></td><td><span class="badge <?=badge_class($r['status'])?>"><?=e($r['status'])?></span></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>open</option><option>reviewing</option><option>resolved</option><option>dismissed</option></select><button class="mini-btn">Save</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No reports yet. The moderation queue is clear.</td></tr><?php endif;?></tbody></table></div></div><?php require 'footer.php'; ?>
